<section class="panel inset"><form method="get" class="inline"><input type="hidden" name="p" value="search"><label>Поиск по доступным проектам, задачам, вехам и документам<input type="search" name="q" maxlength="120" value="<?= h($term) ?>" required></label><button class="primary">Найти</button></form></section>
<?php foreach (['projects'=>'Проекты','tasks'=>'Задачи','milestones'=>'Вехи','documents'=>'Документы'] as $kind=>$label): if (!isset($matches[$kind])) continue; ?><section class="panel"><div class="panelhead"><h2><?= h($label) ?></h2><span class="count"><?= count($matches[$kind]) ?></span></div><?php if (!$matches[$kind]): ?><p class="empty">Ничего не найдено.</p><?php endif ?><?php foreach ($matches[$kind] as $row): ?><div class="splitrow"><a href="<?= h(match($kind) {'documents'=>url('document',['id'=>$row['id']]),'tasks'=>url('task',['id'=>$row['id']]),'milestones'=>url('project',['id'=>$row['project_id'],'milestone'=>$row['id']]).'#milestone-'.$row['id'],default=>url('project',['id'=>$row['id']])}) ?>"><?= h($row['title']) ?></a></div><?php endforeach ?><?php if (count($matches[$kind])===100): ?><p class="inset">Показаны первые 100 результатов. Уточните запрос.</p><?php endif ?></section><?php endforeach ?>
